import { execFile } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";

const run = promisify(execFile);
const root = process.cwd();

/**
 * Artifacts that are both committed and regenerated by `npm run build`.
 *
 * Committing them makes them readable from GitHub and shippable; regenerating
 * them means the committed copy can fall behind the code it describes. Nothing
 * else in the gate can see that, because `build` runs first: `registry:check`
 * and `design:lint` validate the freshly generated files, so a stale committed
 * copy passes every check while describing a component that has since changed.
 */
const GENERATED_ARTIFACTS = ["registry/registry.json", "DESIGN.md"];

/**
 * `provenance.lastModified` is the date of the last commit touching a source
 * file, which makes it the one field that can never be self-consistent: a
 * commit that changes a component also changes that component's date, so the
 * registry committed *in* that change always records the previous one. Left in
 * the comparison it would fail every pull request that touches a component,
 * which is noise rather than drift. It is still generated and still useful —
 * it is only excluded from this equality check.
 */
const VOLATILE_FIELDS = new Set(["lastModified"]);

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key]) => !VOLATILE_FIELDS.has(key))
        .map(([key, entry]) => [key, normalize(entry)]),
    );
  }
  return value;
}

const canonical = (file, contents) =>
  file.endsWith(".json") ? JSON.stringify(normalize(JSON.parse(contents)), null, 2) : contents;

async function git(args) {
  const { stdout } = await run("git", args, { cwd: root, maxBuffer: 64 * 1024 * 1024 });
  return stdout;
}

/** First lines that actually differ, so the failure says what moved. */
function previewDifference(committed, current, limit = 6) {
  const before = committed.split("\n");
  const after = current.split("\n");
  const lines = [];

  for (let index = 0; index < Math.max(before.length, after.length) && lines.length < limit; index += 1) {
    if (before[index] === after[index]) continue;
    if (before[index] !== undefined) lines.push(`  - ${truncate(before[index])}`);
    if (after[index] !== undefined) lines.push(`  + ${truncate(after[index])}`);
  }

  return lines;
}

const truncate = (line) => (line.length > 150 ? `${line.slice(0, 150)}…` : line.trim());

const failures = [];

try {
  await git(["rev-parse", "--is-inside-work-tree"]);
} catch {
  console.error("Drift check failed: not a git repository, so committed output cannot be compared.");
  process.exit(1);
}

for (const file of GENERATED_ARTIFACTS) {
  const current = await fs.readFile(path.join(root, file), "utf8").catch(() => null);
  if (current === null) {
    failures.push(`${file} is missing. Run "npm run build".`);
    continue;
  }

  let committed;
  try {
    committed = await git(["show", `HEAD:${file}`]);
  } catch {
    failures.push(`${file} is generated but not committed. Commit it so the checked-in copy can be compared.`);
    continue;
  }

  let committedCanonical;
  let currentCanonical;
  try {
    committedCanonical = canonical(file, committed);
    currentCanonical = canonical(file, current);
  } catch (error) {
    failures.push(`${file} could not be parsed for comparison: ${error.message}`);
    continue;
  }

  if (committedCanonical === currentCanonical) continue;

  failures.push(
    [
      `${file} does not match what the current source generates.`,
      ...previewDifference(committedCanonical, currentCanonical),
    ].join("\n"),
  );
}

if (failures.length > 0) {
  console.error("Generated output has drifted from source:");
  for (const failure of failures) console.error(`- ${failure}`);
  console.error("");
  console.error('Fix: run "npm run build" and commit the regenerated files alongside the change that moved them.');
  console.error("This check reports drift and does not correct it. See docs/drift-detection.md.");
  process.exit(1);
}

console.log(`Generated output matches source for ${GENERATED_ARTIFACTS.length} artifacts.`);
